<?php
require_once 'config.php'; require_once 'includes/security.php';
$message=''; $error=''; $token=$_GET['token']??($_POST['token']??''); $hash=$token?hash('sha256',$token):'';
if ($_SERVER['REQUEST_METHOD']==='POST') { try { require_csrf(); $new=$_POST['new_password']??''; $confirm=$_POST['confirm_password']??''; if(strlen($new)<8 || !preg_match('/[A-Za-z]/',$new) || !preg_match('/\d/',$new)) throw new RuntimeException('Password must be at least 8 characters and include a letter and a number.'); if($new!==$confirm) throw new RuntimeException('Passwords do not match.'); $stmt=$conn->prepare('SELECT id,user_id FROM password_resets WHERE token_hash=? AND used_at IS NULL AND expires_at>NOW() LIMIT 1'); $stmt->bind_param('s',$hash); $stmt->execute(); $reset=$stmt->get_result()->fetch_assoc(); $stmt->close(); if(!$reset) throw new RuntimeException('This reset link is invalid or expired.'); $password=password_hash($new,PASSWORD_DEFAULT); $stmt=$conn->prepare('UPDATE users SET password=? WHERE id=?'); $stmt->bind_param('si',$password,$reset['user_id']); $stmt->execute(); $stmt->close(); $stmt=$conn->prepare('UPDATE password_resets SET used_at=NOW() WHERE id=?'); $stmt->bind_param('i',$reset['id']); $stmt->execute(); $stmt->close(); audit_log($conn,'reset_password','user',(int)$reset['user_id'],'Password reset completed'); $message='Password reset successfully. You can now sign in.'; $token=''; } catch(Throwable $e){$error=$e->getMessage();} }
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Reset Password | Grievance Portal</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-5"><div class="card border-0 shadow-sm mx-auto" style="max-width:520px"><div class="card-body p-4"><h3>Reset password</h3><?php if($message):?><div class="alert alert-success"><?=e($message)?></div><a href="login.php" class="btn btn-primary w-100">Go to login</a><?php elseif($error):?><div class="alert alert-danger"><?=e($error)?></div><?php else:?><form method="post"><?=csrf_field()?><input type="hidden" name="token" value="<?=e($token)?>"><div class="mb-3"><label class="form-label">New password</label><input class="form-control" type="password" name="new_password" minlength="8" required></div><div class="mb-4"><label class="form-label">Confirm password</label><input class="form-control" type="password" name="confirm_password" minlength="8" required></div><button class="btn btn-primary w-100">Reset password</button></form><?php endif;?></div></div></main></body></html>
